describe('Card Decline Error Handling', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should display error message when card is declined', () => {
    // Intercept the API call to simulate card decline
    cy.intercept('POST', '/api/payment/process', {
      statusCode: 400,
      body: {
        error: 'Card declined',
        message: 'The card you entered was declined. Please try a different card or contact your bank.'
      }
    }).as('cardDecline');

    // Fill in the card details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
    cy.get('[data-testid="card-cvc-input"]').type('123');

    // Submit the payment form
    cy.get('[data-testid="submit-payment-button"]').click();

    // Wait for the card decline API response
    cy.wait('@cardDecline');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Card declined');

    // Verify success message is not displayed
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify form is still visible and user can retry
    cy.get('[data-testid="payment-form"]').should('be.visible');
  });

  it('should handle card decline with retry option', () => {
    // Intercept the API call to simulate card decline
    cy.intercept('POST', '/api/payment/process', {
      statusCode: 400,
      body: {
        error: 'Card declined',
        message: 'The card you entered was declined. Please try a different card or contact your bank.'
      }
    }).as('cardDecline');

    // Fill in the card details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
    cy.get('[data-testid="card-cvc-input"]').type('123');

    // Submit the payment form
    cy.get('[data-testid="submit-payment-button"]').click();

    // Wait for the card decline API response
    cy.wait('@cardDecline');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Card declined');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Click retry button
    cy.get('[data-testid="retry-button"]').click();

    // Verify form is still visible
    cy.get('[data-testid="payment-form"]').should('be.visible');

    // Verify error message is cleared
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify success message is not displayed
    cy.get('[data-testid="success-message"]').should('not.exist');
  });
});
